<section id="proof" class="relative isolate overflow-hidden border-y border-ringside-line bg-ringside-surface-deep py-[clamp(4rem,7vw,7rem)]" aria-labelledby="proof-title">
    <img class="absolute inset-0 -z-10 h-full w-full object-cover object-[center_52%] max-[767px]:h-[52%] max-[767px]:object-[72%_44%]" src="images/marketing/match-result.webp" width="1672" height="941" alt="" aria-hidden="true" loading="lazy">
    <div class="absolute inset-0 -z-10 bg-[linear-gradient(90deg,rgb(6_6_7_/_96%)_0%,rgb(6_6_7_/_90%)_44%,rgb(6_6_7_/_35%)_100%)] max-[767px]:bg-[linear-gradient(180deg,rgb(6_6_7_/_76%)_0%,rgb(6_6_7_/_88%)_38%,rgb(6_6_7_/_98%)_62%,rgb(6_6_7_/_100%)_100%)]" aria-hidden="true"></div>
    <x-page-width class="relative">
        <div class="max-w-[46rem]">
                <x-display-heading tag="h2" id="proof-title" class="max-w-[16ch] text-[clamp(2.5rem,4.2vw,3.75rem)]">A result should carry the whole story.</x-display-heading>
                <p class="mt-6 max-w-[42rem] text-[1.1rem] leading-[1.7] text-ringside-muted">Connect the match you booked to its result, then carry that record into championship history.</p>
                <ol class="mt-10 border-t border-ringside-line" aria-label="Match history">
                    <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                        <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Booked</span>
                        <div><h3 class="font-bold">The match card</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Competitors, referee and championship stay together.</p></div>
                    </li>
                    <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                        <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Completed</span>
                        <div><h3 class="font-bold">The result</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Record the outcome against the match that was booked.</p></div>
                    </li>
                    <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                        <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Carried forward</span>
                        <div><h3 class="font-bold">The title record</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Keep championship history with the matches that shaped it.</p></div>
                    </li>
                </ol>
        </div>
    </x-page-width>
</section>
